import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";

type CreateUserBody = {
  email?: string;
  password?: string;
  full_name?: string;
  role?: string;
  branch_id?: string | null;
};

const allowedRoles = new Set(["admin", "pharmacist", "cashier"]);

/** CORS: browsers send OPTIONS preflight before POST. Without this, web gets 405 and "Add staff" fails. */
const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-api-version",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { status: 204, headers: corsHeaders });
  }

  if (req.method != "POST") {
    return new Response("method_not_allowed", {
      status: 405,
      headers: { ...corsHeaders, "Content-Type": "text/plain" },
    });
  }

  const jwt = req.headers.get("Authorization")?.replace("Bearer ", "") ?? "";
  if (jwt.length == 0) {
    return new Response("unauthorized", {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "text/plain" },
    });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (supabaseUrl == null || anonKey == null || serviceRoleKey == null) {
    return new Response("server_env_missing", {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "text/plain" },
    });
  }

  const callerClient = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: `Bearer ${jwt}` } },
  });

  const { data: userData } = await callerClient.auth.getUser();
  const callerUser = userData.user;
  if (callerUser == null) {
    return new Response("unauthorized", {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "text/plain" },
    });
  }

  const { data: callerProfile, error: callerProfileError } = await callerClient
    .from("profiles")
    .select("team_id, role, is_active")
    .eq("id", callerUser.id)
    .maybeSingle();
  if (callerProfileError != null) {
    return new Response(callerProfileError.message, {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "text/plain" },
    });
  }
  if (callerProfile == null || callerProfile.role != "admin" ||
    callerProfile.is_active != true) {
    return new Response("forbidden", {
      status: 403,
      headers: { ...corsHeaders, "Content-Type": "text/plain" },
    });
  }

  const body = (await req.json()) as CreateUserBody;
  const email = body.email?.trim().toLowerCase();
  const password = body.password;
  const fullName = body.full_name?.trim();
  const role = body.role?.trim();
  const branchId = body.branch_id ?? null;

  if (email == null || password == null || fullName == null || role == null) {
    return new Response("missing_fields", {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "text/plain" },
    });
  }
  if (email.length == 0 || password.length == 0 || fullName.length == 0) {
    return new Response("invalid_fields", {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "text/plain" },
    });
  }
  if (!allowedRoles.has(role)) {
    return new Response("bad_role", {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "text/plain" },
    });
  }

  const adminClient = createClient(supabaseUrl, serviceRoleKey);
  const { data: createdUserData, error: createUserError } = await adminClient
    .auth.admin.createUser({
      email,
      password,
      email_confirm: true,
    });
  if (createUserError != null || createdUserData.user == null) {
    return new Response(createUserError?.message ?? "create_user_failed", {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "text/plain" },
    });
  }

  const createdUserId = createdUserData.user.id;
  const { error: profileInsertError } = await adminClient.from("profiles")
    .insert({
      id: createdUserId,
      team_id: callerProfile.team_id,
      full_name: fullName,
      role,
      branch_id: branchId,
      is_active: true,
    });
  if (profileInsertError != null) {
    await adminClient.auth.admin.deleteUser(createdUserId);
    return new Response(profileInsertError.message, {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "text/plain" },
    });
  }

  return Response.json(
    { id: createdUserId },
    { headers: { ...corsHeaders, "Content-Type": "application/json" } },
  );
});
